import React from 'react';
import { hydrateRoot } from 'react-dom/client';
import './vula.app.css';
import { getVulaRouteParams, loadVulaRoute, VulaRouter, type VulaPage } from './vula';

// Route manifest generated by the Vula CLI
// @ts-ignore
import manifest from '../.vula-routes.client.json';
import Layout from '../app/layout';

class ErrorOverlay extends React.Component<{ children: React.ReactNode }, { error: Error | null }> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { error: null };
  }
  static getDerivedStateFromError(error: Error) {
    return { error };
  }
  render() {
    if (this.state.error) {
      return (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          backgroundColor: 'rgba(0,0,0,0.85)', color: '#ff5555',
          padding: '2rem', zIndex: 9999, fontFamily: 'monospace',
          whiteSpace: 'pre-wrap', overflow: 'auto'
        }}>
          <h2 style={{ color: '#ff5555' }}>⚠ Runtime Error</h2>
          <strong>{this.state.error.message}</strong>
          <br /><br />
          {this.state.error.stack}
          <br />
          <button onClick={() => this.setState({ error: null })} style={{
            marginTop: '1rem', padding: '0.5rem 1rem', background: '#333',
            color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer'
          }}>Dismiss</button>
        </div>
      );
    }
    return this.props.children;
  }
}

async function bootstrap() {
  const rootElement = document.getElementById('root')!;
  const routeIndex = Number(rootElement.dataset.vulaRouteIndex);
  const route = Number.isInteger(routeIndex) ? manifest.routes[routeIndex] : undefined;
  if (!route) throw new Error('Vula could not resolve the server-rendered route');
  const params = getVulaRouteParams(route.path, window.location.pathname);
  if (!params) throw new Error('Vula could not resolve route parameters for the server-rendered page');
  const Component = await loadVulaRoute(route);
  const initialPage: VulaPage = { route, params, Component };
  hydrateRoot(
    rootElement,
    <React.StrictMode>
      <ErrorOverlay>
        <VulaRouter routes={manifest.routes} initialPage={initialPage} layout={Layout} />
      </ErrorOverlay>
    </React.StrictMode>
  );
}

bootstrap();
